package br.com.tapeteskalke.service;
import br.com.tapeteskalke.dto.OperacaoDtos.VendaRequest; import br.com.tapeteskalke.dto.OperacaoDtos.VendaResponse; import br.com.tapeteskalke.dto.OperacaoDtos.CancelarRequest; import br.com.tapeteskalke.entity.*; import br.com.tapeteskalke.exception.*; import br.com.tapeteskalke.repository.*; import br.com.tapeteskalke.security.CurrentUser; import java.math.*; import java.time.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class VendaService { private final VendaRepository vendas; private final ClienteService clientes; private final ProdutoService produtos; private final FuncionarioRepository funcionarios; private final EstoqueService estoque; private final PermissionService permissions; private final CurrentUser current; private final NumeroService numeros; private final Clock clock; private final EntregaRepository entregas; private final ClienteRepository clienteRepo; private final CodigoService codigos;
 public VendaService(VendaRepository vendas,ClienteService clientes,ProdutoService produtos,FuncionarioRepository funcionarios,EstoqueService estoque,PermissionService permissions,CurrentUser current,NumeroService numeros,Clock clock,EntregaRepository entregas,ClienteRepository clienteRepo,CodigoService codigos){this.entregas=entregas;this.clienteRepo=clienteRepo;this.codigos=codigos;this.vendas=vendas;this.clientes=clientes;this.produtos=produtos;this.funcionarios=funcionarios;this.estoque=estoque;this.permissions=permissions;this.current=current;this.numeros=numeros;this.clock=clock;}
 @Transactional public VendaResponse create(VendaRequest r,String key){permissions.action("vendas_criar");if(key==null||key.isBlank())throw new BusinessException("IDEMPOTENCY_KEY_OBRIGATORIA","Informe Idempotency-Key",HttpStatus.BAD_REQUEST);var previous=vendas.findByIdempotencyKey(key);if(previous.isPresent()){if(!current.require().id().equals(previous.get().getCreatedBy()))throw new BusinessException("IDEMPOTENCY_KEY_EM_USO","Idempotency-Key já utilizada por outra venda",HttpStatus.CONFLICT);return response(previous.get());}codigos.require(CodigoService.Tabela.FORMA_PAGAMENTO,r.formaPagamento());var client=clientes.active(r.clienteId());if(r.desconto().signum()<0)throw new BusinessException("DESCONTO_INVALIDO","Desconto inválido",HttpStatus.UNPROCESSABLE_ENTITY);var v=new Venda();v.setNumeroVenda(numeros.nextVenda());v.setCliente(client);v.setVendedor(r.vendedorId()==null||r.vendedorId().isBlank()?null:funcionarios.findById(r.vendedorId()).orElseThrow(()->new ResourceNotFoundException("Funcionário",r.vendedorId())));v.setDataVenda(r.dataVenda()==null?LocalDate.now(clock):r.dataVenda());v.setFormaPagamento(r.formaPagamento());v.setObservacoes(r.observacoes());v.setIdempotencyKey(key);v.setCreatedBy(current.require().id());v.setUpdatedBy(current.require().id());BigDecimal subtotal=BigDecimal.ZERO;Map<String,Produto> locked=new LinkedHashMap<>();for(var item:r.itens().stream().sorted(Comparator.comparing(br.com.tapeteskalke.dto.OperacaoDtos.VendaItem::produtoId)).toList())locked.put(item.produtoId(),produtos.locked(item.produtoId()));for(var input:r.itens()){var p=locked.get(input.produtoId());if(!p.isAtivo()||!p.isPodeSerVendido())throw new BusinessException("PRODUTO_INATIVO","Produto indisponível: "+p.getNome(),HttpStatus.CONFLICT);if(input.quantidade().signum()<=0)throw new BusinessException("QUANTIDADE_INVALIDA","Quantidade deve ser positiva",HttpStatus.UNPROCESSABLE_ENTITY);if(p.getPrecoVenda().signum()<=0)throw new BusinessException("PRODUTO_SEM_PRECO","Produto sem preço de venda cadastrado: "+p.getNome(),HttpStatus.UNPROCESSABLE_ENTITY);var item=new VendaItem();item.setProduto(p);item.setProdutoNomeSnapshot(p.getNome());item.setUnidadeMedidaSnapshot(p.getUnidadeMedida());item.setQuantidade(input.quantidade());item.setPrecoUnitario(p.getPrecoVenda());item.setCustoUnitario(p.getPrecoCusto());item.setSubtotal(p.getPrecoVenda().multiply(input.quantidade()).setScale(2,RoundingMode.HALF_UP));subtotal=subtotal.add(item.getSubtotal());v.addItem(item);}
 if(r.desconto().compareTo(subtotal)>0)throw new BusinessException("DESCONTO_INVALIDO","Desconto não pode superar subtotal",HttpStatus.UNPROCESSABLE_ENTITY);v.setSubtotal(subtotal);v.setDesconto(r.desconto());v.setTotalVenda(subtotal.subtract(r.desconto()));vendas.save(v);for(var item:v.getItens())estoque.change(item.getProduto(),"COMERCIAL",item.getQuantidade().negate(),"SAIDA_VENDA","VENDA",v.getId(),"Venda "+v.getNumeroVenda());recalculateClient(client);return response(v); }
 @Transactional public VendaResponse cancel(String id,CancelarRequest r){permissions.action("vendas_cancelar");var v=vendas.detail(id).orElseThrow(()->new ResourceNotFoundException("Venda",id));if(!"FINALIZADA".equals(v.getStatus()))throw new BusinessException("VENDA_NAO_CANCELAVEL","A venda não pode ser cancelada",HttpStatus.CONFLICT);cancelDelivery(v);Map<String,Produto> locked=new HashMap<>();for(var item:v.getItens().stream().sorted(Comparator.comparing(i->i.getProduto().getId())).toList())locked.put(item.getProduto().getId(),produtos.locked(item.getProduto().getId()));for(var item:v.getItens()){var p=locked.get(item.getProduto().getId());estoque.change(p,"COMERCIAL",item.getQuantidade(),"ESTORNO_VENDA","CANCELAMENTO",v.getId(),"Estorno da venda "+v.getNumeroVenda());}v.setStatus("CANCELADA");v.setCancelledAt(OffsetDateTime.now(clock));v.setCancelledBy(current.require().id());v.setMotivoCancelamento(r.motivo());v.setUpdatedBy(current.require().id());recalculateClient(v.getCliente());return response(v); }
 @Transactional(readOnly=true) public List<VendaResponse> list(){return vendas.listWithClient().stream().map(this::response).toList();} @Transactional(readOnly=true) public VendaResponse get(String id){return response(vendas.detail(id).orElseThrow(()->new ResourceNotFoundException("Venda",id)));}
 // Entrega em rota bloqueia o cancelamento; entrega já realizada é mantida como histórico (vira devolução).
 private void cancelDelivery(Venda v){entregas.findByVendaId(v.getId()).ifPresent(e->{if("EM_ROTA".equals(e.getStatus()))throw new BusinessException("ENTREGA_EM_ROTA","A entrega desta venda está em rota. Aguarde o retorno antes de cancelar",HttpStatus.CONFLICT);if(!"ENTREGUE".equals(e.getStatus())){e.setStatus("CANCELADA");e.setUpdatedBy(current.require().id());}});}
 // Trava o cliente (sempre depois dos produtos, mesma ordem em venda e cancelamento) para vendas simultâneas não sobrescreverem o total.
 private void recalculateClient(Cliente c){clienteRepo.lockById(c.getId());var sales=vendas.finalizedByClient(c.getId());c.setTotalCompras(sales.stream().map(Venda::getTotalVenda).reduce(BigDecimal.ZERO,BigDecimal::add));c.setUltimaCompra(sales.stream().map(Venda::getDataVenda).max(LocalDate::compareTo).orElse(null));c.setUpdatedBy(current.require().id());}
 private VendaResponse response(Venda v){return new VendaResponse(v.getId(),v.getNumeroVenda(),v.getCliente().getNome(),v.getDataVenda(),v.getSubtotal(),v.getDesconto(),v.getTotalVenda(),v.getStatus());}
}